public class PassByValueDemo {
    public static void main(String[] args) {
        int count = 10;
        increment(count);
        System.out.println("count after increment(): " + count); // Still 10!

        Item item = new Item("Book");
        modifyItem(item);
        System.out.println("item.name after modifyItem(): " + item.name); // Notebook!
    }

    public static void increment(int val) {
        val += 5; // Modifies only local copy
    }

    public static void modifyItem(Item i) {
        i.name = "Notebook"; // Mutates shared heap object
    }
}

class Item {
    String name;
    Item(String name) { this.name = name; }
}

