public class InstanceVariablesDemo {
    public static void main(String[] args) {
        Employee emp1 = new Employee();
        emp1.id = 101;
        emp1.name = "Diana";

        Employee emp2 = new Employee();
        emp2.id = 102;
        emp2.name = "Evan";

        // Each instance maintains independent field values
        System.out.println("Emp1: " + emp1.id + " - " + emp1.name);
        System.out.println("Emp2: " + emp2.id + " - " + emp2.name);
    }
}

class Employee {
    int id;       // Instance variable
    String name;  // Instance variable
}

public class VariableScopeDemo {
    public static void main(String[] args) {
        Counter c1 = new Counter();
        c1.increment();
        c1.increment();

        Counter c2 = new Counter();
        c2.increment();

        System.out.println("c1 instance count: " + c1.instanceCount); // 2
        System.out.println("c2 instance count: " + c2.instanceCount); // 1
        System.out.println("Total operations:   " + Counter.totalOperations); // 3
    }
}

class Counter {
    static int totalOperations = 0; // Shared across all instances
    int instanceCount = 0;          // Unique to each instance

    void increment() {
        int step = 1; // Local variable on the stack
        instanceCount += step;
        totalOperations += step;
    }
}

