public class ParameterizedConstructorDemo {
    public static void main(String[] args) {
        User u1 = new User("admin", "admin@domain.com");
        User u2 = new User("guest", "guest@domain.com");

        u1.printProfile();
        u2.printProfile();
    }
}

class User {
    String username;
    String email;

    // Parameterized constructor initializing specific fields
    User(String u, String e) {
        username = u;
